-- PROFILS D'EXEMPLE (60) — à lancer dans Supabase → SQL Editor
-- Ce sont de faux profils (personnes fictives, illustrations générées).
-- Pour les SUPPRIMER plus tard :  delete from auth.users where email like 'demo%@objectif.invalid';

select ('00000000-0000-4000-8000-' || lpad(g::text, 12, '0'))::uuid, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
       'demo' || g || '@objectif.invalid', '', now(), now(), now(), '{"provider":"email","providers":["email"]}', '{}'
from generate_series(1, 60) g
on conflict (id) do nothing;

on conflict (id) do nothing;
